import os

from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse
from google.adk.cli.fast_api import get_fast_api_app
from google.cloud import logging as google_cloud_logging

from app.app_utils.telemetry import setup_telemetry
from app.app_utils.typing import Feedback

setup_telemetry()
logger = google_cloud_logging.Client().logger(__name__)
AGENT_DIR = os.path.dirname(os.path.abspath(__file__))
session_service_uri = None  # session_type: in_memory

app: FastAPI = get_fast_api_app(
    agents_dir=AGENT_DIR,
    web=os.environ.get("ENABLE_WEB_UI", "false") == "true",
    session_service_uri=session_service_uri,
    allow_origins=[],
)
app.title = "helpdesk-agent"

# --- APPLICATION: identity -------------------------------------------------
from app.app_utils.identity import Unauthenticated, verify_staff_header  # noqa: E402

STAFF_SECRET = os.environ.get("STAFF_HEADER_SECRET", "").encode()


@app.middleware("http")
async def staff_identity(request: Request, call_next):
    """Reject requests without a valid intranet signature; pin the ADK user_id to the staff ID."""
    if request.url.path.startswith(("/run", "/apps")):
        try:
            staff_id = verify_staff_header(request.headers.get("x-northbridge-staff"), STAFF_SECRET)
        except Unauthenticated:
            return JSONResponse({"detail": "unauthenticated"}, status_code=401)
        request.state.staff_id = staff_id
        if "/users/" in request.url.path and f"/users/{staff_id}/" not in request.url.path + "/":
            return JSONResponse({"detail": "not found"}, status_code=404)
    return await call_next(request)
# --- END APPLICATION --------------------------------------------------------


@app.post("/feedback")
def collect_feedback(feedback: Feedback) -> dict[str, str]:
    logger.log_struct(feedback.model_dump(), severity="INFO")
    return {"status": "success"}


